import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        StringBuilder sb = new StringBuilder();

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < i; j++) {
                sb.append('*');
            }
            if (i < n) {
                sb.append('\n');
            }
        }

        System.out.print(sb);
    }
}

import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        for (int i = 0; i < n; i++) {
            int num = sc.nextInt();
            boolean prime = num >= 2;

            for (int j = 2; j <= num / j && prime; j++) {
                if (num % j == 0) {
                    prime = false;
                }
            }

            System.out.println(prime ? "Yes" : "No");
        }
    }
}

