import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        for (int i = 0; i <= 2 * n; i++) {
            int level = i <= n ? i : 2 * n - i;

            for (int j = 0; j < n - level; j++) {
                System.out.print(" ");
            }

            for (int j = 0; j < 2 * level + 1; j++) {
                System.out.print("*");
            }

            System.out.println();
        }
    }
}
